enum class LengthUnit(val toMetres: Double) { METRE(1.0), KILOMETRE(1_000.0), FOOT(0.3048) }

@JvmInline
value class Length private constructor(val metres: Double) {
    companion object {
        fun of(amount: Double, unit: LengthUnit) = Length(amount * unit.toMetres)
    }
    operator fun plus(other: Length) = Length(metres + other.metres)
    fun inUnit(unit: LengthUnit) = metres / unit.toMetres
}

val span = Length.of(3.0, LengthUnit.KILOMETRE) + Length.of(500.0, LengthUnit.METRE)

